import{_ as o,o as r,c as e,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Patrick McGarry -- Ceph Community Update","description":"","frontmatter":{"title":"Patrick McGarry -- Ceph Community Update","date":"2015-11-13T00:00:00.000Z","updated":"2015-11-14T00:00:00.000Z","tags":["Ceph社区","分布式存储","开源项目","技术发展","治理结构"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/Patrick_McGarry_--_Ceph_Community_Update.md","filePath":"posts/2015/Patrick_McGarry_--_Ceph_Community_Update.md","lastUpdated":1780459816000}'),n={name:"posts/2015/Patrick_McGarry_--_Ceph_Community_Update.md"};function i(p,t,l,a,g,_){return r(),e("div",null,[...t[0]||(t[0]=[s("<p>本次会议纪要详细记录了2015年SEF Day上，Ceph社区猴子Patrick McGarry的社区更新内容。以下为会议主要内容的总结：</p><p><strong>一、社区发展</strong></p><ol><li><strong>社区活动</strong>： Ceph社区活跃，包括SEF Day、Hackathon等活动，未来计划举办更多活动。</li><li><strong>社区指标</strong>： VectorGia公司提供的SEF指标平台，帮助社区了解性能、调优和硬件配置等信息。</li><li><strong>用户委员会</strong>： 用户委员会由社区成员自发组织，负责社区基础设施、Meetup、Swag等事务。</li><li><strong>Google Summer of Code</strong>： Ceph社区已连续两年参与Google Summer of Code项目，为社区培养新人才。</li><li><strong>Outreach Program</strong>： Ceph社区参与Outreach Program，帮助社区成员进行wiki迁移等任务。</li></ol><p><strong>二、技术发展</strong></p><ol><li><strong>Ceph</strong>： Ceph是一个开源的分布式存储系统，具有对象、块和文件存储功能。</li><li><strong>Liberapay</strong>： Ceph提供Liberapay库，可直接访问对象存储，提高性能并暴露一些酷炫的API。</li><li><strong>Ceph S</strong>： Ceph S预计明年推出，为社区提供更多功能。</li><li><strong>对象类</strong>： Ceph支持对象类，允许在存储节点上执行代码，例如图像缩略图处理、日志清理等。</li><li><strong>部署和编排</strong>： Ceph支持多种部署和编排框架，如Ansible、Chef、Puppet等，并支持Docker容器化。</li><li><strong>测试集群</strong>： Ceph社区提供公用的测试集群，方便社区成员进行测试。</li></ol><p><strong>三、治理</strong></p><ol><li><strong>董事会</strong>： Ceph社区成立董事会，由10名成员组成，负责社区治理。</li><li><strong>项目领导</strong>： Sage为Ceph项目领导，负责项目方向和技术决策。</li><li><strong>非商业成员</strong>： 董事会包含非商业成员，代表用户、学术界和商业利益。</li></ol><p><strong>四、行动计划</strong></p><ol><li><strong>举办更多社区活动</strong>： 计划举办更多SEF Day、Hackathon等活动。</li><li><strong>优化社区指标平台</strong>： 完善Ceph指标平台，提供更多性能和调优信息。</li><li><strong>加强用户委员会建设</strong>： 支持用户委员会工作，提升社区服务质量。</li><li><strong>推进Ceph S项目</strong>： 加快Ceph S项目开发，为社区提供更多功能。</li><li><strong>完善对象类功能</strong>： 推广对象类功能，促进社区创新。</li><li><strong>加强社区治理</strong>： 完善社区治理机制，确保社区健康发展。</li></ol><p><strong>五、其他</strong></p><ol><li><strong>Ceph社区邮件列表</strong>： 欢迎社区成员加入Ceph社区邮件列表，参与社区讨论。</li><li><strong>Ceph YouTube频道</strong>： 欢迎关注Ceph YouTube频道，获取最新社区资讯和技术分享。</li></ol><p>本次会议内容涵盖了Ceph社区的各个方面，包括社区发展、技术进展、治理结构以及行动计划等。通过本次会议，我们可以了解到Ceph社区在技术、治理和社区建设等方面的最新动态和发展方向。</p>",12)])])}const c=o(n,[["render",i]]);export{h as __pageData,c as default};
